#![cfg(all(feature = "ppt", feature = "doc"))]

use file_parse::compound_gate::{JsError, assert_compound_file, assert_sound_compound_file};

enum Expect {
    Value(&'static str),
    Error(&'static str, &'static str),
}
use Expect::{Error, Value};

fn bytes(hex: &str) -> Vec<u8> {
    (0..hex.len() / 2)
        .map(|k| u8::from_str_radix(&hex[2 * k..2 * k + 2], 16).unwrap())
        .collect()
}

fn check(
    function: &str,
    label: &str,
    hex: &str,
    expect: &Expect,
    run: impl Fn(&[u8]) -> Result<String, JsError>,
) {
    let result = run(&bytes(hex));
    match (expect, &result) {
        (Value(want), Ok(got)) => assert_eq!(got, want, "{function}: {label}"),
        (Error(name, message), Err(got)) => {
            assert_eq!(
                (got.name.as_str(), got.message.as_str()),
                (*name, *message),
                "{function}: {label}"
            );
        }
        _ => panic!(
            "{function}: {label}: expected {}, got {result:?}",
            match expect {
                Value(v) => format!("value {v:?}"),
                Error(n, m) => format!("{n}: {m}"),
            }
        ),
    }
}

