#[test]
fn ppt_to_text() {
    for (label, hex, expect) in PPT {
        check("pptToText", label, hex, expect, |b| {
            file_parse::ppt::ppt_to_text(b)
        });
    }
}

#[test]
fn doc_to_text() {
    for (label, hex, expect) in DOC {
        check("docToText", label, hex, expect, |b| {
            file_parse::doc::doc_to_text(b)
        });
    }
}

#[test]
fn compound_gate() {
    for (label, hex, expect) in GATE {
        check("assertCompoundFile", label, hex, expect, |b| {
            assert_compound_file(b)
                .map(|()| String::new())
                .map_err(|e| JsError::new(e.name(), e.message()))
        });
    }
}

#[test]
fn sound_compound_file() {
    for (label, hex, expect) in SOUND {
        let document_type = if label.contains("other characters") {
            "\u{e9}\u{1f600} \u{131}"
        } else {
            "Word 97-2003"
        };
        check("assertSoundCompoundFile", label, hex, expect, |b| {
            assert_sound_compound_file(b, document_type)
                .map(|()| String::new())
                .map_err(JsError::from)
        });
    }
}
